// === Record-based case 2 - same ticket ===
// A refund was already rejected on THIS ticket (Rejection Complaint = yes, set
// by the Zendesk ticket update request sub-workflow when the rejection macro was
// sent, or by an agent on a manual rejection) and the follow-up has just been
// classified as a refund request again.
//
// Runs only after "Is refund request" = r, by decision 2026-09-23 - not on
// thanks, confirmation or complaint replies. The cross-ticket half of case 2
// (a NEW ticket after an earlier rejection) lives in PS prod - Record based
// checks, called from the main flow.
//
// Reads the live ticket rather than the webhook payload, so no Zendesk trigger
// change is needed and an agent's manual "yes" is always seen. If the read
// fails the check does not fire and automation carries on as before.

const cfg = $('Get Project Config').first().json || {};
const resp = $('Case 2: Get ticket').first().json || {};
const live = resp.ticket || {};

// Same switches as 1a/1b/7b: fail-CLOSED on enabled, fail-SAFE on enforce.
function truthy(v) {
  return v === true || v === 1 || v === 'true' || v === '1' || v === 'yes';
}
const enabled = truthy(cfg.record_checks_enabled);
const enforce = truthy(cfg.record_checks_enforce);

// "Yes" option value from cs_project_config (empty = yes).
const rcYes = String(cfg.rejection_complaint_value_yes || 'yes');
const rcFieldId = Number(cfg.ticket_field_rejection_complaint);
const liveFields = Array.isArray(live.custom_fields) ? live.custom_fields : [];
const rcCurrent = liveFields.find(f => Number(f.id) === rcFieldId);
const rejectedBefore = Number.isFinite(rcFieldId) && rcFieldId > 0
  && !!rcCurrent && rcCurrent.value === rcYes;

const matched = enabled && rejectedBefore;
const ticketId = $('Aggregate').first().json.data[0].original_ticket_content.ticket_id;

const lines = [
  'Note: This ticket matched record-based case 2 - a refund was already rejected on this ticket and the customer is requesting a refund again.',
  ''
];

if (enforce) {
  lines.push('Automation has been stopped and no reply was sent to the customer.');
  lines.push('Please review the conversation and handle this ticket manually.');
} else {
  lines.push('MONITORING MODE: the ticket was tagged and this note added, but automation was NOT stopped.');
  lines.push('The bot may still reply to this customer. No agent action is required unless the reply is wrong.');
}

const ticket = {
  comment: { public: false, body: lines.join('\n') }
};

// TAGS. A single-ticket PUT REPLACES the tag array (additional_tags is silently
// discarded), so the live tags from Case 2: Get ticket are merged in.
// record_based_flag matches what the main-flow record-based checks add.
const tags = Array.isArray(live.tags) ? live.tags.slice() : [];
['record_case_2', 'record_based_flag'].forEach(function (t) {
  if (tags.indexOf(t) === -1) tags.push(t);
});
ticket.tags = tags;

if (enforce) {
  // Setting to open is not a solve transition, so required-to-solve fields do
  // not need to ride along.
  const openStatusId = Number(cfg.ticket_custom_status_open_id);
  if (Number.isFinite(openStatusId) && openStatusId > 0) {
    ticket.custom_status_id = openStatusId;
  }

  // Stop automation re-engaging on any further replies.
  const allowFieldId = Number(cfg.ticket_field_allow_automation);
  if (Number.isFinite(allowFieldId) && allowFieldId > 0) {
    ticket.custom_fields = [{ id: allowFieldId, value: '_no_' }];
  }
}

return [{
  json: {
    ticket_id: ticketId,
    rc2_enabled: enabled,
    rc2_enforce: enforce,
    rc2_rejected_before: rejectedBefore,
    rc2_matched: matched,
    rc2_should_block: matched && enforce,
    rc2_ticket_read_error: resp.error ? String(resp.error.message || resp.error) : null,
    tags_sent: tags,
    zendesk_body: { ticket: ticket }
  },
  pairedItem: { item: 0 }
}];

// === Record-based case 6 - replies ===
// The customer asked for a refund in a reply (Is refund request = r) and the
// payments service has a chargeback or dispute on record for them. Same rule as
// the first-message check in PS prod - Record based checks: existence is
// enough, refund requests only (decisions 2026-10-14).
//
// Switches: record_case6_enabled runs the check, record_case6_enforce decides
// whether the ticket is taken out of automation or only tagged.
//
// This node never throws: on any problem it reports "not matched" and hands the
// bot/search payload through untouched, so Has refunded transactions1 and
// everything after it behave exactly as before.

const payload = $('DEV bot/search1').first().json || {};
let c6 = { matched: false, should_block: false };

try {
  const cfg = $('Get Project Config').first().json || {};
  function truthy(v) {
    return v === true || v === 1 || v === 'true' || v === '1' || v === 'yes';
  }
  const enabled = truthy(cfg.record_case6_enabled);
  const enforce = truthy(cfg.record_case6_enforce);

  const body = payload.body || {};
  const chargebacks = Array.isArray(body.chargebackTransactions) ? body.chargebackTransactions : [];
  const matched = enabled && chargebacks.length > 0;

  const ticketId = $('Aggregate').first().json.data[0].original_ticket_content.ticket_id;

  function day(iso) {
    return iso ? String(iso).slice(0, 10) : '?';
  }
  function describe(c) {
    c = c || {};
    const amount = (c.amount != null ? c.amount : '?') + (c.currency ? ' ' + c.currency : '');
    const provider = c.provider && c.provider.type ? c.provider.type : 'unknown provider';
    return '- recorded ' + day(c.chargebackDate) + ', ' + amount + ' disputed, ' + provider +
      ', ' + (c.type || 'unknown type') + ' charge of ' + day(c.transactionDate);
  }

  const lines = [
    'Note: This ticket matched record-based case 6 - the customer has a chargeback or dispute on record and is asking for a refund in a reply.',
    '',
    'Automation has been stopped and no reply was sent to the customer. Please handle this ticket manually.',
    '',
    'Chargebacks / disputes on record (' + chargebacks.length + '):'
  ].concat(chargebacks.map(describe));

  const zendeskBody = {
    ticket: {
      comment: { public: false, body: lines.join('\n') }
    }
  };
  const openStatusId = Number(cfg.ticket_custom_status_open_id);
  if (Number.isFinite(openStatusId) && openStatusId > 0) {
    zendeskBody.ticket.custom_status_id = openStatusId;
  }
  const allowFieldId = Number(cfg.ticket_field_allow_automation);
  if (Number.isFinite(allowFieldId) && allowFieldId > 0) {
    zendeskBody.ticket.custom_fields = [{ id: allowFieldId, value: '_no_' }];
  }

  c6 = {
    matched: matched,
    should_block: matched && enforce,
    enabled: enabled,
    enforce: enforce,
    ticket_id: ticketId,
    chargeback_count: chargebacks.length,
    tags: ['record_case_6', 'record_based_flag'],
    zendesk_body: zendeskBody
  };
} catch (e) {
  c6 = { matched: false, should_block: false, error: String(e && e.message || e) };
}

const out = {};
for (const k in payload) {
  if (Object.prototype.hasOwnProperty.call(payload, k)) out[k] = payload[k];
}
out.case6 = c6;

return [{ json: out, pairedItem: { item: 0 } }];

// Not diverted - hand the classifier output onward so Switch and every branch
// after it see exactly what they saw before claim detection was added.
return [{ json: $('Ticket classification2').first().json, pairedItem: { item: 0 } }];

